using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
namespace Wildfolk.Editor
{
    // Explicit isolated Editor fixture. Time advances used for expiry are labelled in evidence.
    public static class FoodQa
    {
        public static string Phase{get;private set;}="idle";
        private static string Root=>Path.GetFullPath("Captures/food-expansion");
        private static WorldSaveService s;private static PlayerInventory bag;private static PlayerSurvival survival;private static Health health;
        private static NetworkSession host;private static NetworkPlayer actor;
        private static void Log(string text){Directory.CreateDirectory(Root);File.AppendAllText(Root+"/live.tsv",DateTime.UtcNow.ToString("O")+"\t"+Phase+"\t"+text+"\n");}
        private static void Check(bool ok,string text){Log((ok ? "PASS " : "FAIL ")+text);if(!ok)throw new InvalidOperationException(text);}
        private static void Step(string text){Phase=text;Log("begin");}
        private static IEnumerator Guard(IEnumerator flow)
        {var stack=new Stack<IEnumerator>();stack.Push(flow);while(stack.Count>0){bool more;object value;try{more=stack.Peek().MoveNext();value=more ? stack.Peek().Current : null;}catch(Exception e){Phase="failed";Log(e.ToString());yield break;}if(!more){stack.Pop();continue;}if(value is IEnumerator child)stack.Push(child);else yield return value;}Phase="complete";Log("complete");}
        private static IEnumerator Capture(string name)
        {if(Application.isBatchMode)yield break;yield return null;ScreenCapture.CaptureScreenshot(Root+"/"+name+".png");yield return new WaitForEndOfFrame();yield return null;}
        public static void Begin()
        {ContentExpansionQa.Prepare();s=ContentExpansionQa.S;bag=s.Player;survival=bag.GetComponent<PlayerSurvival>();health=bag.GetComponent<Health>();s.World.Animals.enabled=s.World.Renewal.enabled=false;s.World.Animals.Restore(Array.Empty<AnimalSnapshot>(),new AnimalEcologySnapshot());Application.runInBackground=true;Phase="starting";s.StartCoroutine(Guard(Single()));}
        private static void Select(string id,int add=0){if(add>0)bag.Model.Add(s.Catalog.Item(id),add);ContentExpansionQa.Select(id,false);}
        private static bool Use()=>bag.GetComponent<PlayerPrimaryAction>().TryUse();
        private static void Ready(int hp=40)
        {survival.ResetTransient();survival.Model.Restore(new SurvivalModel(survival.Definition).Capture());health.RestoreHealth(hp);health.RestoreCombatTime(0,survival.Definition.RegenDelay);}
        private static IEnumerator Craft(string id)
        {var r=s.Catalog.Recipe(id);foreach(var c in r.Ingredients){var missing=c.Count-bag.Model.CountItem(c.Item);if(missing>0)bag.Model.Add(c.Item,checked((int)missing));}var craft=bag.GetComponent<PlayerCrafting>();craft.SetSelected(r);yield return null;var before=bag.Model.CountItem(r.Result);UnityEngine.Object.FindFirstObjectByType<CraftingPanel>().Cards.Single(c=>c.Recipe==r).CraftButton.onClick.Invoke();Check(craft.Processor.IsBusy,"actual Pot queue accepted "+id);yield return Capture("01-queue-"+id);yield return new WaitForSeconds(r.ProcessingSeconds/craft.Station.Definition.ProcessingSpeed+.2f);Check(craft.Processor.Collect(bag),"collect cooked "+id);Check(bag.Model.CountItem(r.Result)==before+1,"one cooked inventory result "+id);yield return Capture("02-crafted-"+id);}
        private static IEnumerator Single()
        {
            Step("cooking");L.SetLanguage("ko");ContentExpansionQa.Move(Vector2.zero);ContentExpansionQa.Clear(Vector2.zero,12);bag.Model.Restore(new InventoryModel(bag.Model.Capacity).Capture(),s.Catalog);
            var pot=ContentExpansionQa.Place("cooking_pot",new Vector2(2,0)).GetComponent<CraftingStation>();var craft=bag.GetComponent<PlayerCrafting>();craft.OpenStation(pot);
            craft.SetSelected(s.Catalog.Recipe("fish_stew"));yield return Capture("00-existing-food");foreach(var id in new[]{"hunters_stew","forager_soup","trail_broth"})yield return Craft(id);L.SetLanguage("en");craft.SetSelected(s.Catalog.Recipe("forager_soup"));yield return Capture("03-description-en");craft.CloseCrafting();s.World.Session.CloseInventory();L.SetLanguage("ko");
            Step("baseline");Ready();var locomotion=bag.GetComponent<PlayerLocomotion>();locomotion.Restore(0,0);var started=Time.time;yield return new WaitForSeconds(2.1f);var rate=locomotion.Stamina.Current/(Time.time-started);Check(Mathf.Abs(rate-16)<1.5f,"baseline Stamina rate "+rate);var hp=health.Current;started=Time.time;yield return new WaitForSeconds(8.1f);var natural=health.Current-hp;Check(natural>=4 && natural<=5,"baseline natural HP "+natural+" in "+(Time.time-started));
            Step("hunter");Ready(60);health.MarkCombat();var growth=JsonUtility.ToJson(bag.GetComponent<PlayerProgression>().Capture());Select("hunters_stew",2);var count=bag.Model.CountItem(s.Catalog.Item("hunters_stew"));Check(Use(),"Hunter consumed at full nutrition");Check(health.Current==60 && health.Maximum==108,"Hunter max108 without healing current60");Check(survival.Meal.Bonus(MealEffect.NaturalRecovery)==0 && survival.Meal.Bonus(MealEffect.StaminaRecovery)==0,"Hunter supplies exactly one role");Check(!Use() && bag.Model.CountItem(s.Catalog.Item("hunters_stew"))==count-1,"repeat blocked without consuming");Select("healing_salve",2);Check(!Use(),"Meal shares interval with medicine");yield return Capture("04-hunter");
            health.RestoreHealth(108);survival.AdvanceTemporary(151);Check(health.Maximum==100 && health.Current==100 && !survival.Meal.Active,"explicit151s expiry clamps108 to100");yield return Capture("05-expired");Check(JsonUtility.ToJson(bag.GetComponent<PlayerProgression>().Capture())==growth,"temporary food never changes Skill ranks");
            Step("replacement");Ready(40);Select("hunters_stew");Check(Use(),"new Hunter course");yield return new WaitForSeconds(4.1f);Select("forager_soup",1);Check(Use(),"Forager replaces Hunter after interval");Check(health.Maximum==100 && survival.Meal.Bonus(MealEffect.MaximumHealth)==0 && survival.Meal.Bonus(MealEffect.NaturalRecovery)==.15f,"one replacement slot");
            Step("forager");survival.Model.SetMeters(100,100);health.RestoreHealth(40);health.RestoreCombatTime(0,survival.Definition.RegenDelay);hp=health.Current;started=Time.time;yield return new WaitForSeconds(8.1f);var gained=health.Current-hp;Check(gained>=5 && gained<=6,"Forager natural HP "+gained+" in "+(Time.time-started));yield return Capture("06-forager");survival.Model.SetMeters(60,100);hp=health.Current;survival.AdvanceNaturalRecovery(20);Check(health.Current==hp,"low nutrition blocks Forager");survival.Model.SetMeters(100,100);health.MarkCombat();survival.AdvanceNaturalRecovery(20);Check(health.Current==hp,"recent combat blocks Forager");health.RestoreCombatTime(0,survival.Definition.RegenDelay);survival.Model.Restore(s.Catalog.Item("raw_water_cup").Consumable);survival.AdvanceNaturalRecovery(20);Check(health.Current==hp,"raw-water recovery block still applies");
            Step("trail");survival.Model.Restore(new SurvivalModel(survival.Definition).Capture());Select("trail_broth",1);Check(Use(),"Trail replaces Forager");var stats=bag.GetComponent<CharacterStats>();Check(survival.Meal.Bonus(MealEffect.NaturalRecovery)==0 && Mathf.Abs(stats.RecoveryMultiplier-1.1f)<.001f,"Trail alone gives10percent Stamina recovery");locomotion.Restore(0,0);started=Time.time;yield return new WaitForSeconds(2.1f);rate=locomotion.Stamina.Current/(Time.time-started);Check(Mathf.Abs(rate-17.6f)<1.5f,"actual Trail Stamina rate "+rate);Check(locomotion.Stamina.Maximum==100,"Trail never raises MaxStamina");locomotion.Restore(60,0);Check(locomotion.Stamina.Spend(24),"normal Dash cost fixture");yield return new WaitForSeconds(.5f);Check(Mathf.Abs(locomotion.Stamina.Current-36)<.01f,"normal recovery delay preserved");yield return Capture("07-trail");
            Step("food-medicine");Ready();Select("bone_broth",2);hp=health.Current;Check(Use() && health.Current==hp+18 && !survival.Meal.Active,"Bone Broth instant18 with no MaxHP meal");Ready();locomotion.Restore(0,1.2f);Select("restorative_broth",2);Check(Use() && locomotion.Stamina.Current==35 && !survival.Meal.Active,"Restorative instant35 with no recovery buff");Ready();locomotion.Restore(0,1.2f);Select("trail_ration",2);Check(Use() && locomotion.Stamina.Current==20 && !survival.Meal.Active,"Campfire Ration instant20 no Meal");Ready();Select("healing_salve");hp=health.Current;Check(Use() && health.Current==hp+30,"Salve remains instant30");Ready();Select("field_dressing",2);hp=health.Current;Check(Use() && health.Current==hp && survival.Treatment.Active,"Dressing remains gradual not instant");yield return Capture("08-boundaries");
            Step("save-load");Ready(100);Select("hunters_stew",1);Check(Use(),"Hunter before Save");health.RestoreHealth(108);count=bag.Model.CountItem(s.Catalog.Item("hunters_stew"));var snapshot=s.Capture();Check(snapshot.Version==11 && snapshot.Player.HP==100 && health.Current==108,"Save snapshot clamps temporary excess without modifying live HP");Check(s.Save(),"isolated Save11");var game=s.Repository.Read(s.Validate);s.Apply(game);yield return null;Check(!survival.Meal.Active && health.Maximum==100 && health.Current==100,"Load removes temporary meal without replay");Check(bag.Model.CountItem(s.Catalog.Item("hunters_stew"))==count,"Load retains exactly consumed stack");yield return Capture("09-loaded");
            Step("death");Ready(60);Select("hunters_stew",1);Check(Use(),"Hunter before death");health.ApplyDamage(10000,true);Check(!survival.Meal.Active && health.Maximum==100,"death removes Meal modifier");
        }
        public static void BeginHost()
        {if(!DevelopmentProfile.Isolated)throw new InvalidOperationException("Isolated QA required");UnityEngine.Object.FindFirstObjectByType<HomeScreen>().OpenMultiplayer();host=NetworkSession.Instance;host.WorldRepository=new SaveRepository(Root+"/host/"+Guid.NewGuid().ToString("N")+"/world.json");host.ProfileOverride=Guid.NewGuid().ToString("N");host.NewWorldGenerationVersion=3;Application.runInBackground=true;Phase="starting";host.StartCoroutine(Guard(HostFlow()));}
        private static IEnumerator EnterHost()
        {var task=host.Host(ConnectionRoute.LocalNetwork);yield return new WaitUntil(()=>task.IsCompleted);Check(task.Result,"local Host "+host.LastFailure);Check(host.EnterGame(),"enter multiplayer");var until=Time.realtimeSinceStartup+45;while(Time.realtimeSinceStartup<until){actor=NetworkPlayer.Active.FirstOrDefault(p=>p.IsSpawned && p.NetworkObject.IsPlayerObject);if(actor!=null && NetworkCreatureWorld.Active!=null && NetworkCreatureWorld.Active.Ready)break;yield return null;}Check(actor!=null && NetworkCreatureWorld.Active.Ready,"Host world ready");actor.Motor.enabled=actor.GetComponent<PlayerInputAdapter>().enabled=false;var w=NetworkCreatureWorld.Active;w.Clock.enabled=w.Animals.enabled=w.Goblins.enabled=w.Night.enabled=w.World.Renewal.enabled=false;w.World.Chunks.DrainPending();yield return null;}
        private static IEnumerator HostFlow()
        {
            Step("host");yield return EnterHost();var c=NetworkCreatureWorld.Active.Catalog;var inventory=actor.GetComponent<PlayerInventory>();var v=actor.GetComponent<PlayerSurvival>();var h=actor.Health;var stats=actor.GetComponent<CharacterStats>();inventory.Model.Restore(new InventoryModel(inventory.Model.Capacity).Capture(),c);foreach(var id in new[]{"hunters_stew","forager_soup","trail_broth"})inventory.Model.Add(c.Item(id),2);h.RestoreHealth(60);h.MarkCombat();inventory.SelectSlot(0);
            Check(actor.ExecutePrimary(100),"server consumes Hunter");Check(h.Current==60 && h.Maximum==108,"server MaxHP no free heal");Check(!actor.ExecutePrimary(100) && inventory.Model.CountItem(c.Item("hunters_stew"))==1,"duplicate RPC does not consume twice");Check(actor.Status.Value.MealItem==Array.IndexOf(c.Items,c.Item("hunters_stew")) && actor.Status.Value.MealUntil>actor.NetworkManager.ServerTime.Time,"meal identity and end time replicated");yield return Capture("10-host-hunter");yield return new WaitForSeconds(4.1f);inventory.SelectSlot(1);Check(!actor.ExecutePrimary(100),"stale request rejected after cooldown");Check(actor.ExecutePrimary(101),"server replaces with Forager");Check(h.Maximum==100 && v.Meal.Bonus(MealEffect.MaximumHealth)==0,"old server modifier removed");v.Model.SetMeters(100,100);h.RestoreHealth(40);h.RestoreCombatTime(0,v.Definition.RegenDelay);var hp=h.Current;yield return new WaitForSeconds(8.1f);Check(h.Current>=hp+5 && h.Current<=hp+6,"server natural recovery includes Forager with disabled survival Update");inventory.SelectSlot(2);Check(actor.ExecutePrimary(102) && Mathf.Abs(stats.RecoveryMultiplier-1.1f)<.001f && v.Meal.Bonus(MealEffect.NaturalRecovery)==0,"server Trail replaces Forager");Check(!actor.ExecutePrimary(102),"duplicate Trail rejected");yield return Capture("11-host-trail");v.AdvanceTemporary(151);Check(!v.Meal.Active && Mathf.Abs(stats.RecoveryMultiplier-1)<.001f,"server explicit151s expiry removes modifier");yield return new WaitForSeconds(4.1f);inventory.SelectSlot(0);Check(actor.ExecutePrimary(103),"server Hunter before Save");h.RestoreHealth(108);Check(host.TrySaveWorld(),"Host Save11 with temporary maxHP");Check(h.Current==108,"saving does not clamp live server HP");host.Leave();yield return new WaitUntil(()=>host.State==NetworkSessionState.Idle);yield return new WaitForSecondsRealtime(.3f);
            Step("rehost");yield return EnterHost();inventory=actor.GetComponent<PlayerInventory>();v=actor.GetComponent<PlayerSurvival>();Check(actor.Health.Maximum==100 && actor.Health.Current==100 && !v.Meal.Active,"reHost removes meal and clamps persistent HP");Check(inventory.Model.CountItem(c.Item("hunters_stew"))==0 && inventory.Model.CountItem(c.Item("forager_soup"))==1 && inventory.Model.CountItem(c.Item("trail_broth"))==1,"reHost preserves exact consumption");yield return Capture("12-rehost");
        }
        public static void BeginHostTimers()
        {if(!DevelopmentProfile.Isolated)throw new InvalidOperationException("Isolated QA required");UnityEngine.Object.FindFirstObjectByType<HomeScreen>().OpenMultiplayer();host=NetworkSession.Instance;host.WorldRepository=new SaveRepository(Root+"/timers/"+Guid.NewGuid().ToString("N")+"/world.json");host.ProfileOverride=Guid.NewGuid().ToString("N");host.NewWorldGenerationVersion=3;Phase="starting";host.StartCoroutine(Guard(HostTimers()));}
        private static IEnumerator HostTimers()
        {
            Step("host-timers");yield return EnterHost();var v=actor.GetComponent<PlayerSurvival>();var c=actor.Catalog;var inventory=actor.GetComponent<PlayerInventory>();inventory.Model.Restore(new InventoryModel(inventory.Model.Capacity).Capture(),c);inventory.Model.Add(c.Item("forager_soup"),1);inventory.SelectSlot(0);actor.Health.RestoreHealth(40);actor.Health.RestoreCombatTime(0,v.Definition.RegenDelay);Check(actor.ExecutePrimary(1),"Forager timer fixture consumed");v.Model.Restore(c.Item("raw_water_cup").Consumable);var h=v.Model.Hunger;var thirst=v.Model.Thirst;v.AdvanceNaturalRecovery(20);Check(actor.Health.Current==40,"Raw Water blocks server Forager");v.AdvanceTemporary(59);Check(v.Model.RecoveryBlockRemaining>0 && v.Model.RecoveryBlockRemaining<=1,"server temporary update advances59s water penalty");v.AdvanceTemporary(2);Check(v.Model.RecoveryBlockRemaining==0 && v.Model.DrainPenaltyRemaining==0 && v.Model.DrainMultiplier==1,"server water effects expire without permanent block");Check(v.Model.Hunger==h && v.Model.Thirst==thirst,"temporary timer fix does not enable MP nutrition drain");v.AdvanceNaturalRecovery(2);Check(actor.Health.Current==41 && v.Meal.Active,"existing server natural recovery resumes with Forager");yield return Capture("17-host-water-expiry");
        }
    }
}
